package cn.lvxu.travel;
import android.view.*;import android.widget.*;import android.graphics.*;import android.graphics.drawable.*;import android.content.res.ColorStateList;
/** Resolve contrast against each actual surface, including independently mixed custom colors. */
final class ThemeViews {
 static int background(Drawable d,int inherited){if(d instanceof ColorDrawable){int c=((ColorDrawable)d).getColor();return Color.alpha(c)==255?c:inherited;}if(d instanceof GradientDrawable){ColorStateList colors=((GradientDrawable)d).getColor();if(colors!=null&&Color.alpha(colors.getDefaultColor())==255)return colors.getDefaultColor();}if(d instanceof InsetDrawable)return background(((InsetDrawable)d).getDrawable(),inherited);if(d instanceof LayerDrawable){LayerDrawable layers=(LayerDrawable)d;for(int i=0;i<layers.getNumberOfLayers();i++)inherited=background(layers.getDrawable(i),inherited);}return inherited;}
 static void apply(View view,int parentColor){int color=background(view.getBackground(),parentColor);if(view instanceof TextView){TextView t=(TextView)view;t.setTextColor(MainActivity.readable(t.getCurrentTextColor(),color));if(view instanceof EditText)t.setHintTextColor(MainActivity.readable(t.getCurrentHintTextColor(),color));}if(view instanceof CompoundButton){int accent=MainActivity.readable(MainActivity.GREEN,color);ColorStateList tint=new ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{accent,MainActivity.readable(MainActivity.MUTED,color)});((CompoundButton)view).setButtonTintList(tint);if(view instanceof Switch){((Switch)view).setThumbTintList(tint);((Switch)view).setTrackTintList(ColorStateList.valueOf(MainActivity.blend(accent,color,.35f)));}}if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)apply(group.getChildAt(i),color);}}
}
